e_en":"1:18 Tesla Cybertruck 4-Drive Lights","title_zh":"1:18 特斯拉 Cybertruck 四向遥控汽车灯光款","category":"online-toys-collectibles","source_category":"玩具潮玩","price":13.5,"cost_per_item":0,"stock":20,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260527/4415425/d267c2b6452ad2e2fc7c29c64e075cbf.jpg?x-oss-process=style/zhutu","sku":"1222798","sku_is_extracted":false,"source_created_at":"2026-05-27 12:46:08"},{"source_id":"1222775","title_en":"1:16 Convertible Remote-Controlled Vehicles Can Charge USB","title_zh":"1:16可敞篷遥控汽车可usb充电","category":"online-toys-collectibles","source_category":"玩具潮玩","price":15.9,"cost_per_item":0,"stock":20,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260527/4415425/06b2e2f5a6fbb90da2c974ff13b3472c.jpg?x-oss-process=style/zhutu","sku":"1222775","sku_is_extracted":false,"source_created_at":"2026-05-27 12:33:34"},{"source_id":"1222759","title_en":"1:14 Remotely Piloted Car Lights","title_zh":"1：14 遥控汽车灯光款","category":"online-toys-collectibles","source_category":"玩具潮玩","price":12.9,"cost_per_item":0,"stock":20,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260527/4415425/48cbc83bffa6c2bd73528b7d06bba18b.jpeg?x-oss-process=style/zhutu","sku":"1222759","sku_is_extracted":false,"source_created_at":"2026-05-27 12:20:41"},{"source_id":"1202561","title_en":"Four Omelets","title_zh":"四格煎蛋锅","category":"online-kitchen-essentials","source_category":"厨房好物","price":15.9,"cost_per_item":0,"stock":100,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260519/4415425/e88133ee1992fccb682feeff78f4d48d.png?x-oss-process=style/zhutu","sku":"1202561","sku_is_extracted":false,"source_created_at":"2026-05-19 10:58:10"},{"source_id":"1197136","title_en":"4pc AA Battery","title_zh":"4pcs AA Battery电池","category":"online-batteries-power-boards","source_category":"电池与插排","price":4.99,"cost_per_item":1.84,"stock":97,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260516/4415425/7dacee809d4ee61d4b4094157b5ac804.jpg?x-oss-process=style/zhutu","sku":"1197136","sku_is_extracted":false,"source_created_at":"2026-05-16 17:31:08"},{"source_id":"1188084","title_en":"Red Balloon","title_zh":"红色气球","category":"online-party-celebrations","source_category":"节日生日","price":2.99,"cost_per_item":2.69,"stock":100,"sales":0,"published":true,"image":"https://oss-sc.juhuodong.com/uploads/mall6702/20260514/4415425/fcd30d2d9951c83edd957192ddeeb2bf.jpg?x-oss-process=style/zhutu","sku":"1188084","sku_is_extracted":false,"source_created_at":"2026-05-14 15:56:47"}]$online_shop_products$::jsonb
  ) as source (
    source_id text,
    title_en text,
    title_zh text,
    category text,
    source_category text,
    price numeric,
    cost_per_item numeric,
    stock integer,
    sales integer,
    published boolean,
    image text,
    sku text,
    sku_is_extracted boolean,
    source_created_at text
  )
), normalized_source as (
  select
    source.*,
    regexp_replace(lower(trim(source.title_zh)), '[[:space:][:punct:]]+', '', 'g') as normalized_title_zh,
    regexp_replace(lower(trim(source.title_en)), '[[:space:][:punct:]]+', '', 'g') as normalized_title_en
  from source_rows source
), matched as (
  select
    source.*,
    offline.id as offline_product_id,
    offline.price as offline_price,
    offline.match_kind
  from normalized_source source
  left join lateral (
    select
      product.id,
      product.price,
      case
        when source.sku_is_extracted and lower(trim(product.sku)) = lower(trim(source.sku)) then 'sku'
        when length(source.normalized_title_zh) >= 4 and source.normalized_title_zh in (
          regexp_replace(lower(trim(product.title)), '[[:space:][:punct:]]+', '', 'g'),
          regexp_replace(lower(trim(product.title_zh)), '[[:space:][:punct:]]+', '', 'g')
        ) then 'title_zh'
        else 'title_en'
      end as match_kind
    from public.products product
    where product.sales_channel = 'offline'
      and product.deleted_at is null
      and coalesce(product.tags, '') <> '__gogoshop_purged__'
      and (
        (
          source.sku_is_extracted
          and nullif(trim(product.sku), '') is not null
          and lower(trim(product.sku)) = lower(trim(source.sku))
        )
        or (
          length(source.normalized_title_zh) >= 4
          and source.normalized_title_zh in (
            regexp_replace(lower(trim(product.title)), '[[:space:][:punct:]]+', '', 'g'),
            regexp_replace(lower(trim(product.title_zh)), '[[:space:][:punct:]]+', '', 'g')
          )
        )
        or (
          length(source.normalized_title_en) >= 6
          and source.normalized_title_en in (
            regexp_replace(lower(trim(product.title)), '[[:space:][:punct:]]+', '', 'g'),
            regexp_replace(lower(trim(product.title_en)), '[[:space:][:punct:]]+', '', 'g')
          )
        )
      )
    order by
      case
        when source.sku_is_extracted and lower(trim(product.sku)) = lower(trim(source.sku)) then 0
        when source.normalized_title_zh in (
          regexp_replace(lower(trim(product.title)), '[[:space:][:punct:]]+', '', 'g'),
          regexp_replace(lower(trim(product.title_zh)), '[[:space:][:punct:]]+', '', 'g')
        ) then 1
        else 2
      end,
      product.updated_at desc,
      product.id
    limit 1
  ) offline on true
)
, inserted as (
  insert into public.products (
    id, title, title_en, title_zh, category,
    description, description_en, description_zh,
    price, compare_at_price, cost_per_item, stock, sales, published, sales_channel,
    image, images, vendor, sku, barcode, tags,
    source_url, source_currency, source_price, source_variants, source_attributes,
    deleted_at, deleted_was_published, updated_at
  )
  select
    'online-kdh-' || matched.source_id,
    matched.title_en,
    matched.title_en,
    matched.title_zh,
    matched.category,
    '',
    '',
    '',
    case when matched.offline_price > 0 then matched.offline_price else matched.price end,
    0,
    matched.cost_per_item,
    matched.stock,
    matched.sales,
    matched.published,
    'online',
    matched.image,
    jsonb_build_array(matched.image),
    'GO GO SHOP',
    matched.sku,
    '',
    concat_ws(',', 'online-shop', 'kuaidihe', 'source-id:' || matched.source_id),
    'https://sc.kuaidihe.com/web/fronted.php?r=mall%2Fgoods%2Fedit&id=' || matched.source_id,
    'NZD',
    matched.cost_per_item,
    '[]'::jsonb,
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'source_system', 'GO GO SHOP Online Shop',
      'source_id', matched.source_id,
      'source_category', matched.source_category,
      'source_created_at', matched.source_created_at,
      'source_retail_price', matched.price,
      'price_source', case when matched.offline_price > 0 then 'offline' else 'online-shop' end,
      'matched_offline_product_id', matched.offline_product_id,
      'match_kind', matched.match_kind
    ))),
    null,
    false,
    now()
  from matched
  on conflict (id) do nothing
  returning id
)
select count(*)::int as inserted_products from inserted;

commit;

select
  count(*)::int as imported_products,
  count(*) filter (where published)::int as published_products,
  count(*) filter (where not published)::int as draft_products,
  count(*) filter (
    where source_attributes @> '[{"price_source":"offline"}]'::jsonb
  )::int as duplicate_prices_from_offline,
  sum(stock)::int as stock_units,
  count(*) filter (where nullif(trim(image), '') is not null)::int as products_with_images
from public.products
where id like 'online-kdh-%'
  and sales_channel = 'online'
  and deleted_at is null;
